mapper.select:
SELECT hostname name,ip
FROM traffic_abnormal_machine
WHERE nmsServer_Id = #{nmsServiceId};


SELECT REDIRECT_NUM ,MONITOR_NUM,REPLACE_NUM
FROM pxy_total_report
    WHERE REPORT_TIME >= #{start}
    AND REPORT_TIME < #{end}


        SELECT if((sum(b.INOCTETS) - a.INOCTETS ) >0  ,sum(b.INOCTETS) - a.INOCTETS ,sum(b.INOCTETS)) as INOCTETS,
				if((sum(b.OUTOCTETS) - a.OUTOCTETS ) >0  ,sum(b.OUTOCTETS) - a.OUTOCTETS ,sum(b.OUTOCTETS)) as OUTOCTETS,
				'Akmola' area,
				#{start} time
        FROM (
              SELECT  sum(INOCTETS) INOCTETS,sum(OUTOCTETS) OUTOCTETS
              FROM traffic_netflow_port_info
              WHERE RECV_TIME >= #{before}
              and RECV_TIME<#{start}) a,
              traffic_netflow_port_info b
        WHERE b.RECV_TIME >= #{start}
        and b.RECV_TIME < #{end}


SELECT RECV_TIME
FROM traffic_netflow_port_info
  WHERE RECV_TIME < #{end}
  ORDER BY RECV_TIME desc
  LIMIT 1;
